import os
import time

from taf.internal.gnb.oam.coam.vdu.client.fh_licensed.v1 import (
    ApiClient,
    ApiException,
    Configuration,
    StatusApi
)

from taf.gnb.oam.coam.vdu.exceptions import TimeoutException
from taf.gnb.oam.coam.vdu.services.fh_licensed.http_client import FHLicensedv1HttpClient
from taf.gnb.oam.coam.vdu.services.sec.sec_licensed_v1 import SECLicensedv1
from taf.gnb.oam.coam.vdu.services.sec.sec_v1 import SECv1
from taf.gnb.oam.coam.vdu.utilities.logger import log_request_response
from taf.gnb.oam.coam.vdu.utilities.m2m_interface_availability_checker import (
    m2m_interface_availability_check,
)
from taf.gnb.oam.coam.vdu.utilities.poll_status import poll_status
from taf.gnb.oam.coam.vdu.utilities.token_provider import auto_token_refresh
from taf.gnb.oam.coam.vdu.utilities.token_storage import TokenStorage


@auto_token_refresh(api_exception=ApiException)
class FHLicensedv1:
    def __init__(self, con_details):
        self.con_details = con_details
        self.token_storage = TokenStorage(connection_name=con_details.alias)
        self.sec = SECLicensedv1.get_instance(connection_name=con_details.alias) \
            if con_details.use_m2m else SECv1.get_instance(connection_name=con_details.alias)

        conf = Configuration()
        conf.verify_ssl = False
        conf.host = con_details.get_api_client_configuration(original_endpoint=conf.host)
        self.configuration = conf

        api_client = ApiClient(configuration=conf)
        api_client.request = log_request_response(api_client.request)

        self.status_api = StatusApi(api_client=api_client)
        self.local_client = FHLicensedv1HttpClient(base_url=con_details.base_url,
                                                   connection_alias=con_details.alias)

    @m2m_interface_availability_check
    def get_alds_selection_mode(self, timeout=30):
        return self.local_client.get_alds_selection_mode(timeout=timeout)

    @m2m_interface_availability_check
    def get_ald_select_mode_operation_status(self, operation_id, timeout=30):
        return self.local_client.get_ald_select_mode_operation_status(operation_id=operation_id, timeout=timeout)

    @m2m_interface_availability_check
    def trigger_ald_selection_mode(self, ald_selection_mode, timeout=30):
        return self.local_client.trigger_ald_selection_mode(ald_selection_mode=ald_selection_mode, timeout=timeout)

    @m2m_interface_availability_check
    def set_ret_configuration(self, target_dn="", timeout=30, **kwargs):
        return self.local_client.set_ret_configuration(target_dn=target_dn, timeout=timeout, **kwargs)

    @m2m_interface_availability_check
    def get_ret_configuration_status(self, operation_id, timeout=30):
        return self.status_api.get_ret_configuration(operation_id=operation_id, _request_timeout=timeout)

    @m2m_interface_availability_check
    def create_ald_reset(self, target_dn, type='soft', timeout=30):
        return self.local_client.create_ald_reset(target_dn=target_dn, type=type, timeout=timeout)

    @m2m_interface_availability_check
    def get_ald_reset_status(self, operation_id, timeout=30):
        return self.local_client.get_ald_reset_status(operation_id=operation_id, timeout=timeout)

    @m2m_interface_availability_check
    def get_rmods_syncinfolist(self, timeout=30):
        return self.status_api.rmods_sync_info_list_get(_request_timeout=timeout)

    @m2m_interface_availability_check
    def get_real_time_measurements(self, rmods_runtime_distnames=None, start_time=None, timeout=30):
        return self.local_client.get_real_time_measurements(rmods_runtime_distnames=rmods_runtime_distnames,
                                                            start_time=start_time,
                                                            timeout=timeout)

    @m2m_interface_availability_check
    def get_rmod_measurements_by_id(self, rmod_id, limit_to=None, timeout=60):
        return self.local_client.get_rmod_measurements_by_id(rmod_id=rmod_id, limit_to=limit_to, timeout=timeout)

    @m2m_interface_availability_check
    def reset_rmods(self, rmods_list, reset_reason='user', graceful_cell_shutdown=False, wait_for_completion=False, timeout=30):
        operation = self.local_client.reset_rmods(rmods_list=rmods_list, reset_reason=reset_reason,
                                             graceful_cell_shutdown=graceful_cell_shutdown, timeout=timeout)

        if wait_for_completion:
            method_name = "get_status_of_reset_rmods"

            operation = poll_status(instance=self.local_client, method_name=method_name,
                               operation_id=operation["id"], timeout=timeout)

        return operation

    @m2m_interface_availability_check
    def get_reset_rmods_operation_status(self, operation_id, timeout=30):
        return self.local_client.get_status_of_reset_rmods(operation_id=operation_id, timeout=timeout)

    @m2m_interface_availability_check
    def start_antenna_monitoring(self, antennas, timeout=30, wait_for_completion=False):
        operation = self.local_client.start_antenna_monitoring(antennas=antennas, timeout=timeout)

        if wait_for_completion:
            method_name = "get_antenna_monitoring_status"

            operation = poll_status(instance=self.local_client, method_name=method_name,
                                    monitor_id=operation["monitorId"], timeout=timeout)

        return operation

    @m2m_interface_availability_check
    def get_antenna_monitoring_status(self, monitor_id, timeout=30):
        return self.local_client.get_antenna_monitoring_status(monitor_id=monitor_id, timeout=timeout)

    @m2m_interface_availability_check
    def stop_antenna_monitoring(self, monitor_id, timeout=30):
        self.local_client.stop_antenna_monitoring(monitor_id=monitor_id, timeout=timeout)

    @m2m_interface_availability_check
    def get_antenna_monitoring_results(self, monitor_id, timeout=30):
        return self.local_client.get_antenna_monitoring_results(monitor_id=monitor_id, timeout=timeout)

    @m2m_interface_availability_check
    def get_antenna_monitoring_result_file(self, directory, timeout=30):
        response = self.local_client.get_antenna_monitoring_result_file(directory=directory, timeout=timeout)
        file_id = response['headers']['Content-Disposition'][22: -1]
        file_path = os.path.join(directory, file_id)
        with open(file_path, 'wb+') as f:
            f.write(response['content'])
        return file_path

    @m2m_interface_availability_check
    def start_rf_scan_test(self, ru_dn, signal, antenna=None, antenna_carrier=None, antenna_panel=None, timeout=30):
        return self.local_client.start_rf_scan_test(ru_dn=ru_dn, signal=signal, antenna=antenna, antenna_carrier=antenna_carrier,
                                                    antenna_panel=antenna_panel, timeout=timeout)

    @m2m_interface_availability_check
    def get_rf_scan_test_operation_status(self, operation_id, timeout=30):
        return self.local_client.get_rf_scan_test_operation_status(operation_id=operation_id, timeout=timeout)

    @m2m_interface_availability_check
    def delete_rf_scan_test_operation(self, operation_id, timeout=30):
        self.local_client.delete_rf_scan_test_operation(operation_id=operation_id,
                                                        timeout=timeout)

    @m2m_interface_availability_check
    def cancel_rf_scan_test_operation(self, timeout=30):
        return self.local_client.cancel_rf_scan_test_operation(timeout=timeout)

    @m2m_interface_availability_check
    def get_rf_scan_test_cancellation_status(self, operation_id, timeout=30):
        return self.local_client.get_rf_scan_test_cancellation_status(operation_id=operation_id,
                                                                      timeout=timeout)

    @m2m_interface_availability_check
    def delete_rf_scan_test_cancel_operation(self, operation_id, timeout=30):
        self.local_client.delete_rf_scan_test_cancel_operation(operation_id=operation_id,
                                                                      timeout=timeout)

    @m2m_interface_availability_check
    def get_rf_scan_test_file(self, local_path, local_file_name, timeout=30):
        response = self.local_client.get_rf_scan_test_file(timeout=timeout)
        file_path = os.path.join(local_path, local_file_name)
        with open(file_path, 'wb+') as f:
            f.write(response)
        return file_path

    @m2m_interface_availability_check
    def start_diagnostic_rf_statistics_diagnostic_test(self, target_rmod_id=-1, act_remote_rf_diag=True, rf_temperature_high_threshold=80,
                                                       rf_temperature_low_threshold=-5, timeout=60):
        stop_time = time.time() + timeout
        trigger_test = self.local_client.start_diagnostic_rf_statistics_diagnostic_test(target_rmod_id=target_rmod_id,
                                                                                        act_remote_rf_diag=act_remote_rf_diag,
                                                                                        high_threshold=rf_temperature_high_threshold,
                                                                                        low_threshold=rf_temperature_low_threshold)

        operation_id = trigger_test["operationId"]
        info = self.local_client.get_diagnostic_rf_statistics_diagnostic_test_status(operation_id=operation_id)

        while time.time() < stop_time:
            if info["status"] == "success":
                return

            time.sleep(3)

            info = self.local_client.get_diagnostic_rf_statistics_diagnostic_test_status(operation_id=operation_id)

        raise TimeoutException(f"Operation timeout exceeded. Operation status is {info['status']}, reason is {info['reason']}")

    @m2m_interface_availability_check
    def get_diagnostic_rf_statistics_diagnostic_test_results(self, timeout=60):
        return self.local_client.get_diagnostic_rf_statistics_diagnostic_test_results(timeout=timeout)
